+import type OpenAI from 'openai';
+
+// Self-serve fine-tuning job creation ends on 2027-01-06 (OpenAI deprecations page).
+export const FINE_TUNING_CUTOFF = new Date('2027-01-06T00:00:00Z');
+
+// Replacement for the shut-down gpt-3.5-turbo (Oct 23, 2026). NOTE: this is the
+// inference substitute from the deprecations table; its fine-tunability is unverified.
+export const FINE_TUNING_BASE_MODEL = 'gpt-5.6-terra';
+
+export class FineTuningUnavailableError extends Error {
+  constructor(message: string) {
+    super(message);
+    this.name = 'FineTuningUnavailableError';
+  }
+}
+
+export async function createFineTuningJob(
+  client: OpenAI,
+  params: OpenAI.FineTuning.JobCreateParams,
+  now: Date = new Date(),
+) {
+  if (now >= FINE_TUNING_CUTOFF) {
+    throw new FineTuningUnavailableError(
+      'Self-serve fine-tuning job creation ended on 2027-01-06. Use prompt-based customization with a current model, or contact OpenAI about non-self-serve access.',
+    );
+  }
+  return client.fineTuning.jobs.create(params);
+}
